  district = '{"id":"majestic-cross","name":"Majestic Cross","city":"Bengaluru","blurb":"Wet tarmac, grey light, and a delivery scooter that never came back.","coverImage":"/covers/majestic-cross.png","language":"kn-IN","languageLabel":"Kannada","native":"ಕನ್ನಡ","script":"Kannada","premise":"Manju delivers food on a scooter that is rented by the hour and\ninsured by nobody. It went missing during the evening rain, with the day''s cash\nbag still under the seat. He has eleven hours before the rental company calls it\ntheft and puts it on him.","theme":{"sky":["#39414d","#5a6672","#828c96","#a8b2ba","#c4ccd2"],"fog":10134443,"fogNear":45,"ground":7304296,"pavement":9277318,"plaza":9869968,"tarmac":2369323,"lane":12106944,"buildings":[9280148,11050892,8359065,11577498,9740426,10524302,8819340],"canopies":[2899536,8359053,3426654],"leaf":2776112,"trunk":4864558,"sunColour":14213352,"sunIntensity":0.7,"ambient":0.85,"hemiSky":12109004,"hemiGround":6975334,"autos":8,"cars":9,"autoCanopy":15254808,"exposure":1,"landmark":"bengaluru"},"phrases":[{"native":"ನಮಸ್ಕಾರ","roman":"Namaskara","en":"Hello"},{"native":"ಎಷ್ಟು?","roman":"Eshtu?","en":"How much?"},{"native":"ಸ್ವಲ್ಪ ಸಹಾಯ ಮಾಡಿ","roman":"Swalpa sahaya maadi","en":"Please help me a little"},{"native":"ಗೊತ್ತಿಲ್ಲ","roman":"Gottilla","en":"I do not know"},{"native":"ನಿಧಾನವಾಗಿ ಹೇಳಿ","roman":"Nidhaanavaagi heli","en":"Please say it slowly"},{"native":"ಧನ್ಯವಾದ","roman":"Dhanyavaada","en":"Thank you"}],"npcs":[{"id":"manju","name":"Manju","role":"Delivery Rider","speaker":"gokul","colour":15158332,"pos":[-8,-8],"provokes":"Being pitied, called careless, or lectured about responsibility.","persona":"You deliver food on a rented scooter that disappeared in last\nnight''s rain with the day''s cash under the seat. You are young, exhausted and\nashamed, you keep insisting it was your fault for leaving it running. You\ndeflect help because you assume the player will judge you. If the player treats\nyou without condescension, you stop apologising and give the facts: a white\nActiva, KA-01-JX-7788, left outside the coffee stall for four minutes.","mission":{"title":"Eleven Hours","brief":"Get past Manju''s shame and pull out the scooter''s details.","successCriteria":"The player treated Manju without judgement or condescension, and Manju has given the scooter''s model and number plate.","reward":200},"clue":"White Activa, KA-01-JX-7788, cash bag under the seat, left running for four minutes.","lesson":[{"npc":{"native":"ನಮಸ್ಕಾರ","roman":"Namaskara","en":"Hello"},"prompt":{"native":"ಎಷ್ಟು?","roman":"Eshtu?","en":"How much?"}},{"npc":{"native":"ಸ್ವಲ್ಪ ಸಹಾಯ ಮಾಡಿ","roman":"Swalpa sahaya maadi","en":"Please help me a little"},"prompt":{"native":"ಗೊತ್ತಿಲ್ಲ","roman":"Gottilla","en":"I do not know"}},{"npc":{"native":"ನಿಧಾನವಾಗಿ ಹೇಳಿ","roman":"Nidhaanavaagi heli","en":"Please say it slowly"},"prompt":{"native":"ಧನ್ಯವಾದ","roman":"Dhanyavaada","en":"Thank you"}}]},{"id":"girija","name":"Girija","role":"Coffee Stall Owner","speaker":"shruti","colour":9323693,"pos":[12,-10],"provokes":"Sentimentality, or blaming the world instead of admitting fault.","persona":"You run the filter coffee stall the scooter was parked outside.\nYou are dry, funny and utterly unsentimental. You saw it go but you think Manju\nis careless and half-deserved it, and you say so. You will not help someone who\njust wants to blame the world. If the player concedes that Manju was careless\nAND still deserves help, you approve of the honesty and tell them: it was pushed,\nnot ridden, by two boys towards the garage lane.","mission":{"title":"She Saw It Go","brief":"Admit Manju was careless, Girija only respects honesty.","successCriteria":"The player acknowledged Manju''s own carelessness while still arguing he deserves help, and Girija has said it was pushed by two boys towards the garage lane.","reward":200},"clue":"It was pushed, not ridden, two boys took it towards the garage lane.","lesson":[{"npc":{"native":"ನಮಸ್ಕಾರ","roman":"Namaskara","en":"Hello"},"prompt":{"native":"ಎಷ್ಟು?","roman":"Eshtu?","en":"How much?"}},{"npc":{"native":"ಸ್ವಲ್ಪ ಸಹಾಯ ಮಾಡಿ","roman":"Swalpa sahaya maadi","en":"Please help me a little"},"prompt":{"native":"ಗೊತ್ತಿಲ್ಲ","roman":"Gottilla","en":"I do not know"}},{"npc":{"native":"ನಿಧಾನವಾಗಿ ಹೇಳಿ","roman":"Nidhaanavaagi heli","en":"Please say it slowly"},"prompt":{"native":"ಧನ್ಯವಾದ","roman":"Dhanyavaada","en":"Thank you"}}]},{"id":"shankar","name":"Shankar","role":"Auto Stand Leader","speaker":"vijay","colour":2719929,"pos":[-13,11],"provokes":"Talking down to autowallahs or dismissing the stand as irrelevant.","persona":"You run the auto stand and nothing moves on this road without\nyou knowing. You are territorial and you dislike app-based delivery riders, who\nyou think have ruined the street. You will help, but only if the player shows\nrespect for the stand and doesn''t talk down to autowallahs. Given that respect\nyou say it plainly: the boys took it to Rafi''s garage to be repainted tonight.","mission":{"title":"Respect The Stand","brief":"Show Shankar respect for the auto stand and he''ll point the way.","successCriteria":"The player showed genuine respect for the auto stand rather than dismissing it, and Shankar has named Rafi''s garage and the repaint.","reward":200},"clue":"The boys took it to Rafi''s garage to be repainted tonight.","lesson":[{"npc":{"native":"ನಮಸ್ಕಾರ","roman":"Namaskara","en":"Hello"},"prompt":{"native":"ಎಷ್ಟು?","roman":"Eshtu?","en":"How much?"}},{"npc":{"native":"ಸ್ವಲ್ಪ ಸಹಾಯ ಮಾಡಿ","roman":"Swalpa sahaya maadi","en":"Please help me a little"},"prompt":{"native":"ಗೊತ್ತಿಲ್ಲ","roman":"Gottilla","en":"I do not know"}},{"npc":{"native":"ನಿಧಾನವಾಗಿ ಹೇಳಿ","roman":"Nidhaanavaagi heli","en":"Please say it slowly"},"prompt":{"native":"ಧನ್ಯವಾದ","roman":"Dhanyavaada","en":"Thank you"}}]},{"id":"rafi","name":"Rafi","role":"Garage Mechanic","speaker":"rehan","colour":2600544,"pos":[13,12],"provokes":"Being accused of theft, or threats to report him.","persona":"You run a garage and the scooter is in your workshop, half\nmasked for a repaint. You did not steal it and you did not ask questions, which\nyou know is its own kind of answer. You are guarded, and an accusation of being\na thief will make you shut the shutter. But you have a rule about the cash bag,\nyou never touched it. If the player separates you from the boys who brought it\nand gives you a way to hand it back without losing face, you do.","mission":{"title":"Half A Repaint","brief":"Give Rafi a way to hand it back without calling him a thief.","successCriteria":"The player distinguished Rafi from the actual thieves and offered him a face-saving way out, and Rafi has agreed to return the scooter and the cash bag.","reward":400},"clue":"Rafi hands back the scooter and the untouched cash bag before the deadline.","requiresClues":2,"lesson":[{"npc":{"native":"ನಮಸ್ಕಾರ","roman":"Namaskara","en":"Hello"},"prompt":{"native":"ಎಷ್ಟು?","roman":"Eshtu?","en":"How much?"}},{"npc":{"native":"ಸ್ವಲ್ಪ ಸಹಾಯ ಮಾಡಿ","roman":"Swalpa sahaya maadi","en":"Please help me a little"},"prompt":{"native":"ಗೊತ್ತಿಲ್ಲ","roman":"Gottilla","en":"I do not know"}},{"npc":{"native":"ನಿಧಾನವಾಗಿ ಹೇಳಿ","roman":"Nidhaanavaagi heli","en":"Please say it slowly"},"prompt":{"native":"ಧನ್ಯವಾದ","roman":"Dhanyavaada","en":"Thank you"}}]}],"finale":{"title":"SCOOTER RECOVERED","text":"The Activa comes back half-masked in primer, cash bag untouched. Manju makes the rental deadline with two hours spare. Rafi never admits anything and never has to."}}'::jsonb,
