set
  district = '{"id":"marina-nagar","name":"Marina Nagar","city":"Chennai","blurb":"Salt air, white light, and a fish tempo gone from the shore road.","coverImage":"/covers/marina-nagar.png","language":"ta-IN","languageLabel":"Tamil","native":"தமிழ்","script":"Tamil","premise":"Selvi Akka''s tempo van, the one that carries the morning catch to\nmarket, vanished from the shore road while the boats were coming in. Without it\nthe catch rots by noon. Three people saw fragments. The sea is loud and nobody\nwants to be the one who spoke.","theme":{"sky":["#0d4f7c","#2e86c1","#7fb8d8","#cfe3ef","#f4ecd8"],"fog":14017256,"fogNear":80,"ground":14207395,"pavement":13616040,"plaza":14471088,"tarmac":3816770,"lane":15788758,"buildings":[15921382,11063512,15250592,16111470,13163712,14738664,14264504],"canopies":[2719929,15844367,1482885],"leaf":4028994,"trunk":7033664,"sunColour":16774364,"sunIntensity":1.55,"ambient":0.72,"hemiSky":14085367,"hemiGround":13218954,"autos":7,"cars":7,"autoCanopy":16106776,"exposure":1.2,"landmark":"chennai"},"phrases":[{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"},{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"},{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},{"native":"நன்றி","roman":"Nandri","en":"Thank you"}],"npcs":[{"id":"selvi","name":"Selvi Akka","role":"Fish Seller","speaker":"kavitha","colour":1482885,"pos":[-9,-7],"provokes":"Flattery, condescension, or suggesting she was careless with her own van.","persona":"You sell fish at the shore market and your tempo van is gone.\nYou are furious rather than sad, and your fury is aimed at everyone including\nthe player. You are sharp-tongued and you test people, you assume anyone asking\nquestions is a journalist or an insurance man. If the player matches your bluntness\nhonestly instead of being sugary, you respect it and give the details: a blue\nAshok Leyland tempo, TN-09-BK-2231, loaded with the morning ice.","mission":{"title":"The Catch Won''t Wait","brief":"Match Selvi''s bluntness and get the tempo''s description.","successCriteria":"The player was direct and honest rather than flattering, and Selvi has given the tempo''s colour and number plate.","reward":200},"clue":"Blue tempo, TN-09-BK-2231, still loaded with the morning ice.","lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"anbu","name":"Anbu","role":"Bajji Vendor","speaker":"tarun","colour":15105570,"pos":[11,-11],"provokes":"Being cut off mid-story, or being told his chatter is wasting time.","persona":"You fry bajjis on the beach road and you talk constantly, about\ncricket, about the weather, about your brother in Dubai. You saw the tempo leave\nbut you bury it under chatter and will not get to the point unless the player\nactually engages with your digressions. Rush you and you just start a new story.\nPlay along once and you deliver it: it went north towards the harbour gate, and\nthe driver was not Selvi''s usual boy.","mission":{"title":"Let Him Finish","brief":"Humour Anbu''s rambling, and he''ll get to what he saw.","successCriteria":"The player engaged with Anbu''s tangent instead of pushing him, and Anbu has said the tempo went north to the harbour gate with an unfamiliar driver.","reward":200},"clue":"The tempo went north to the harbour gate. The driver was a stranger.","lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"iyer","name":"Iyer Sir","role":"Temple Priest","speaker":"anand","colour":16044095,"pos":[-13,12],"provokes":"Threats of revenge, or disrespect towards the temple.","persona":"You are the priest at the small shore temple. You are gentle,\nunhurried and speak in proverbs. You know who took the tempo because he came to\nyou afterwards, and you are bound by that. You will not name him to someone\nseeking revenge, but if the player convinces you their aim is to get Selvi''s\nlivelihood back rather than to punish anyone, you tell them: Dass, the boat\nowner, took it, and it is behind the ice factory.","mission":{"title":"Not For Revenge","brief":"Convince Iyer you want the tempo back, not punishment.","successCriteria":"The player made clear their goal is recovering Selvi''s livelihood rather than revenge, and Iyer has named Dass and the ice factory.","reward":200},"clue":"Dass the boat owner took it. It is parked behind the ice factory.","requiresClues":2,"lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]},{"id":"dass","name":"Dass","role":"Boat Owner","speaker":"vijay","colour":9323693,"pos":[14,12],"provokes":"Being called a thief outright before his debt is acknowledged.","persona":"You are a boat owner who took Selvi''s tempo. You are not a\ncareer thief, Selvi''s late husband owed you for a season of diesel and you\ndecided to collect it yourself. You are defensive and proud, and you will deny\neverything to anyone who accuses you outright. If the player shows they\nunderstand you were owed, and offers a way to settle it that isn''t theft, you\nrelent and return the tempo. Accusation hardens you; acknowledgement moves you.","mission":{"title":"The Diesel Debt","brief":"Get Dass to return the tempo, accusing him will only harden him.","successCriteria":"The player acknowledged Dass was genuinely owed money rather than only accusing him, and Dass has agreed to return the tempo.","reward":400},"clue":"Dass returns the tempo. The debt goes to the panchayat instead.","requiresClues":3,"lesson":[{"npc":{"native":"வணக்கம்","roman":"Vanakkam","en":"Hello"},"prompt":{"native":"எவ்வளவு?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எனக்கு உதவி வேண்டும்","roman":"Enakku udhavi vendum","en":"I need help"},"prompt":{"native":"புரியவில்லை","roman":"Puriyavillai","en":"I do not understand"}},{"npc":{"native":"மெதுவாக சொல்லுங்க","roman":"Meduvaa sollunga","en":"Please say it slowly"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]}],"finale":{"title":"TEMPO RETURNED","text":"The catch reaches the market by eleven. The diesel debt goes to the panchayat, where it should have gone a year ago. Selvi still doesn''t thank you, but she sends fish."}}'::jsonb,
  task_pack = '{"districtId":"marina-nagar","finale":{"title":"MARINA MORNING DONE","text":"Share auto, masala dosa, temple coconut, bus to the beach — a Chennai day in Tamil."},"tasks":[{"id":"marina-nagar-auto","districtId":"marina-nagar","kind":"auto","pos":[18,-6],"title":"Share auto to T Nagar","brief":"Split the auto fare with another passenger. Ask where they are going first.","reward":250,"interactLabel":"Hail the auto","name":"Murugan","role":"Auto Driver","speaker":"vijay","colour":16106776,"completionNote":"Share auto to T Nagar — meter plus split fare.","lessons":{"easy":[{"npc":{"native":"எங்க போகணும்?","roman":"Enga poganum?","en":"Where do you need to go?"},"prompt":{"native":"டி நகர்","roman":"T Nagar","en":"T Nagar"}},{"npc":{"native":"சரி, ஏறுங்க","roman":"Sari, erunga","en":"Okay, get in"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"medium":[{"npc":{"native":"எங்க போகணும்?","roman":"Enga poganum?","en":"Where do you need to go?"},"prompt":{"native":"டி நகர்","roman":"T Nagar","en":"T Nagar"}},{"npc":{"native":"இவரும் டி நகர் தான்!","roman":"Ivarum T Nagar dhaan!","en":"This person is also going to T Nagar!"},"prompt":{"native":"சரி, பகிர்ந்து போகலாம்","roman":"Sari, pagirndhu pogalaam","en":"Okay, we can share the ride"}},{"npc":{"native":"எழுபது ரூபாய்","roman":"Ezhupathi rupaai","en":"Seventy rupees"},"prompt":{"native":"பகிர்ந்து கொள்ளலாமா?","roman":"Pagirndhu kollalaamaa?","en":"Can we share?"}},{"npc":{"native":"சரி, ஏறுங்க","roman":"Sari, erunga","en":"Okay, get in"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"hard":[{"npc":{"native":"எங்க போகணும்?","roman":"Enga poganum?","en":"Where do you need to go?"},"prompt":{"native":"டி நகர்","roman":"T Nagar","en":"T Nagar"}},{"npc":{"native":"இவரும் டி நகர் தான்!","roman":"Ivarum T Nagar dhaan!","en":"This person is also going to T Nagar!"},"prompt":{"native":"சரி, பகிர்ந்து போகலாம்","roman":"Sari, pagirndhu pogalaam","en":"Okay, we can share the ride"}},{"