ative":"ஒரு மசாலா தோசை","roman":"Oru masala dosai","en":"One masala dosa"}},{"npc":{"native":"சுட சுட வரும்!","roman":"Suda suda varum!","en":"It''ll come piping hot!"},"prompt":{"native":"சரி, காத்திருக்கிறேன்","roman":"Sari, kaathirukkiren","en":"Okay, I''ll wait"}},{"npc":{"native":"காபி?","roman":"Kaapi?","en":"Coffee?"},"prompt":{"native":"ஆம், ஒரு காபி","roman":"Aam, oru kaapi","en":"Yes, one coffee"}},{"npc":{"native":"சட்னி extra?","roman":"Chutney extra?","en":"Extra chutney?"},"prompt":{"native":"ஆம், கொடுங்க","roman":"Aam, kodunga","en":"Yes, give some"}},{"npc":{"native":"எழுபத்து ஐந்து ரூபாய்","roman":"Ezhupathu aindhu rupaai","en":"Seventy-five rupees"},"prompt":{"native":"எவ்வளavu?","roman":"Evvalavu?","en":"How much?"}}]}},{"id":"marina-nagar-temple","districtId":"marina-nagar","kind":"temple","pos":[8,20],"title":"Coconut at the temple","brief":"Buy a coconut for archana at the shore temple stall.","reward":200,"interactLabel":"Buy prasad","name":"Iyer","role":"Temple Stall","speaker":"kavitha","colour":9323693,"completionNote":"Coconut and kumkum — ready for archana.","lessons":{"easy":[{"npc":{"native":"தேங்காய் வேணுமா?","roman":"Thengai venumaa?","en":"Do you want a coconut?"},"prompt":{"native":"ஆம், ஒரு தேங்காய்","roman":"Aam, oru thengai","en":"Yes, one coconut"}},{"npc":{"native":"எடுத்துக்கோங்க","roman":"Eduthukkonga","en":"Take it"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"medium":[{"npc":{"native":"தேங்காய் வேணுமா?","roman":"Thengai venumaa?","en":"Do you want a coconut?"},"prompt":{"native":"ஆம், ஒரு தேங்காய்","roman":"Aam, oru thengai","en":"Yes, one coconut"}},{"npc":{"native":"பூஜை நேரம் ஆரம்பம்!","roman":"Poojai neram aarambam!","en":"Puja time is starting!"},"prompt":{"native":"சரி, சீக்கிரம் பண்ணுங்க","roman":"Sari, seekiram pannunga","en":"Okay, please hurry"}},{"npc":{"native":"முப்பது ரூபாய்","roman":"Muppathu rupaai","en":"Thirty rupees"},"prompt":{"native":"எவ்வளavu?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"எடுத்துக்கோங்க","roman":"Eduthukkonga","en":"Take it"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"hard":[{"npc":{"native":"தேங்காய் வேணுமா?","roman":"Thengai venumaa?","en":"Do you want a coconut?"},"prompt":{"native":"ஆம், ஒரு தேங்காய்","roman":"Aam, oru thengai","en":"Yes, one coconut"}},{"npc":{"native":"பூஜை நேரம் ஆரம்பம்!","roman":"Poojai neram aarambam!","en":"Puja time is starting!"},"prompt":{"native":"சரி, சீக்கிரம் பண்ணுங்க","roman":"Sari, seekiram pannunga","en":"Okay, please hurry"}},{"npc":{"native":"முப்பது ரூபாய்","roman":"Muppathu rupaai","en":"Thirty rupees"},"prompt":{"native":"எவ்வளavu?","roman":"Evvalavu?","en":"How much?"}},{"npc":{"native":"குங்குமம் வேணுமா?","roman":"Kungumam venumaa?","en":"Want kumkum too?"},"prompt":{"native":"ஆம், கொடுங்க","roman":"Aam, kodunga","en":"Yes, please"}},{"npc":{"native":"எடுத்துக்கோங்க","roman":"Eduthukkonga","en":"Take it"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]}},{"id":"marina-nagar-bus","districtId":"marina-nagar","kind":"bus","pos":[-6,-22],"title":"Beach bus ticket","brief":"Get a ticket to Marina Beach on the city bus.","reward":220,"interactLabel":"Buy bus ticket","name":"Dass","role":"Conductor","speaker":"shubh","colour":2719929,"completionNote":"Ticket to Marina Beach — keep it for checking.","lessons":{"easy":[{"npc":{"native":"எங்க போறீங்க?","roman":"Enga poringa?","en":"Where are you going?"},"prompt":{"native":"மெரினா beach","roman":"Marina Beach","en":"Marina Beach"}},{"npc":{"native":"போங்க","roman":"Ponga","en":"Go ahead"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"medium":[{"npc":{"native":"எங்க போறீங்க?","roman":"Enga poringa?","en":"Where are you going?"},"prompt":{"native":"மெரினா beach","roman":"Marina Beach","en":"Marina Beach"}},{"npc":{"native":"பின்னாடி ஏறுங்க!","roman":"Pinnadi erunga!","en":"Board from the back!"},"prompt":{"native":"சரி, பின்னாடி ஏறுகிறேன்","roman":"Sari, pinnadi erukiren","en":"Okay, I''m boarding from the back"}},{"npc":{"native":"பதினைந்து ரூபாய்","roman":"Pathinaidu rupaai","en":"Fifteen rupees"},"prompt":{"native":"ஒரு டிக்கெட்","roman":"Oru ticket","en":"One ticket"}},{"npc":{"native":"போங்க","roman":"Ponga","en":"Go ahead"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}],"hard":[{"npc":{"native":"எங்க போறீங்க?","roman":"Enga poringa?","en":"Where are you going?"},"prompt":{"native":"மெரினா beach","roman":"Marina Beach","en":"Marina Beach"}},{"npc":{"native":"பின்னாடி ஏறுங்க!","roman":"Pinnadi erunga!","en":"Board from the back!"},"prompt":{"native":"சரி, பின்னாடி ஏறுகிறேன்","roman":"Sari, pinnadi erukiren","en":"Okay, I''m boarding from the back"}},{"npc":{"native":"பதினைந்து ரூபாய்","roman":"Pathinaidu rupaai","en":"Fifteen rupees"},"prompt":{"native":"ஒரு டிக்கெட்","roman":"Oru ticket","en":"One ticket"}},{"npc":{"native":"சில்லறை இருக்கா?","roman":"Sillara irukkaa?","en":"Got change?"},"prompt":{"native":"ஆம், இதோ","roman":"Aam, itho","en":"Yes, here"}},{"npc":{"native":"போங்க","roman":"Ponga","en":"Go ahead"},"prompt":{"native":"நன்றி","roman":"Nandri","en":"Thank you"}}]}}]}'::jsonb,
