াঁ, এক পacket","roman":"Hyaa, ek packet","en":"Yes, one packet"}},{"npc":{"native":"ঘণ্টা বাজছে!","roman":"Ghonta bajche!","en":"The bell is ringing!"},"prompt":{"native":"ঠিক আছে, তাড়াতাড়ি আসছি","roman":"Thik ache, taratari aschi","en":"Okay, coming quickly"}},{"npc":{"native":"পঁচিশ টাকা","roman":"Pochish taka","en":"Twenty-five taka"},"prompt":{"native":"কত?","roman":"Koto?","en":"How much?"}},{"npc":{"native":"সিঁদুর লাগবে?","roman":"Sindur lagbe?","en":"Need vermillion?"},"prompt":{"native":"হ্যাঁ, দিন","roman":"Hyaa, din","en":"Yes, give it"}},{"npc":{"native":"নিন","roman":"Nin","en":"Take it"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]}},{"id":"park-gully-bus","districtId":"park-gully","kind":"bus","pos":[-5,-21],"title":"Tram ticket","brief":"Buy a tram ticket to Esplanade at the stop.","reward":220,"interactLabel":"Buy tram ticket","name":"Nazrul","role":"Ticket Seller","speaker":"soham","colour":1482885,"completionNote":"Tram ticket to Esplanade — validate before boarding.","lessons":{"easy":[{"npc":{"native":"কোথায়?","roman":"Kothay?","en":"Where to?"},"prompt":{"native":"এসপ্ল্যানেড","roman":"Esplanade","en":"Esplanade"}},{"npc":{"native":"যান","roman":"Jan","en":"Go"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}],"medium":[{"npc":{"native":"কোথায়?","roman":"Kothay?","en":"Where to?"},"prompt":{"native":"এসপ্ল্যানেড","roman":"Esplanade","en":"Esplanade"}},{"npc":{"native":"টram আসছে!","roman":"Tram asche!","en":"Tram is coming!"},"prompt":{"native":"ঠিক আছে, টram এ উঠব","roman":"Thik ache, tram e uthbo","en":"Okay, I''ll board the tram"}},{"npc":{"native":"দশ টাকা","roman":"Dash taka","en":"Ten taka"},"prompt":{"native":"একটা ticket","roman":"Ekta ticket","en":"One ticket"}},{"npc":{"native":"যান","roman":"Jan","en":"Go"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}],"hard":[{"npc":{"native":"কোথায়?","roman":"Kothay?","en":"Where to?"},"prompt":{"native":"এসপ্ল্যানেড","roman":"Esplanade","en":"Esplanade"}},{"npc":{"native":"টram আসছে!","roman":"Tram asche!","en":"Tram is coming!"},"prompt":{"native":"ঠিক আছে, টram এ উঠব","roman":"Thik ache, tram e uthbo","en":"Okay, I''ll board the tram"}},{"npc":{"native":"দশ টাকা","roman":"Dash taka","en":"Ten taka"},"prompt":{"native":"একটা ticket","roman":"Ekta ticket","en":"One ticket"}},{"npc":{"native":"খুচরো আছে?","roman":"Khuchro ache?","en":"Got change?"},"prompt":{"native":"হ্যাঁ, নিন","roman":"Hyaa, nin","en":"Yes, take it"}},{"npc":{"native":"যান","roman":"Jan","en":"Go"},"prompt":{"native":"ধন্যবাদ","roman":"Dhonnobad","en":"Thank you"}}]}}]}'::jsonb,
